extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var dirs := ['res://assets/audio', 'res://assets/fonts', 'res://assets/images', 'res://ui', 'res://core', 'res://story']
	for d in dirs:
		if not check('dir_' + d, DirAccess.dir_exists_absolute(d), 'La cartella ' + d + ' deve esistere nel progetto'):
			return

	if not check('file_intro', FileAccess.file_exists('res://story/intro.json'), 'Il file res://story/intro.json deve esistere'):
		return

	var file := FileAccess.open('res://story/intro.json', FileAccess.READ)
	if not check('open_intro', file != null, 'Impossibile aprire res://story/intro.json'):
		return

	var content := file.get_as_text()
	file.close()

	var data = JSON.parse_string(content)
	if not check('json_valid', data != null and typeof(data) == TYPE_DICTIONARY, 'intro.json deve contenere un oggetto JSON valido'):
		return

	var dict: Dictionary = data
	check('has_title', dict.has('title') and typeof(dict['title']) == TYPE_STRING, 'intro.json deve contenere la chiave title con una stringa')

	var has_lines := dict.has('lines') and typeof(dict['lines']) == TYPE_ARRAY
	if check('has_lines', has_lines, 'intro.json deve contenere la chiave lines con un array'):
		var lines: Array = dict['lines']
		check('lines_not_empty', lines.size() > 0 and typeof(lines[0]) == TYPE_STRING, 'L array lines deve contenere almeno una stringa')

extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	if not check('file_exists', FileAccess.file_exists('res://core/systems_map.json'), 'Il file res://core/systems_map.json deve esistere'):
		return

	var file := FileAccess.open('res://core/systems_map.json', FileAccess.READ)
	if not check('file_open', file != null, 'Impossibile aprire res://core/systems_map.json'):
		return

	var content := file.get_as_text()
	file.close()

	var data = JSON.parse_string(content)
	if not check('json_valid', data != null and typeof(data) == TYPE_DICTIONARY, 'systems_map.json deve contenere un oggetto JSON valido'):
		return

	var dict: Dictionary = data
	if not check('has_systems', dict.has('systems') and typeof(dict['systems']) == TYPE_ARRAY, 'systems_map.json deve contenere la chiave systems con un array'):
		return

	var systems: Array = dict['systems']
	if not check('count_systems', systems.size() == 5, 'L array systems deve contenere esattamente 5 sistemi'):
		return

	var required_ids := ['dialogue_ui', 'visual_scene', 'audio_manager', 'story_interpreter', 'game_state']
	var found_ids := {}
	var orders := {}

	for item in systems:
		if typeof(item) != TYPE_DICTIONARY:
			check('item_dict', false, 'Ogni elemento in systems deve essere un oggetto JSON')
			return
		var sys: Dictionary = item
		if not (sys.has('id') and sys.has('order') and sys.has('dependencies')):
			check('item_keys', false, 'Ogni sistema deve contenere id, order e dependencies')
			return
		var sys_id = sys['id']
		if typeof(sys_id) == TYPE_STRING:
			found_ids[sys_id] = sys
			orders[sys_id] = sys['order']

	for req_id in required_ids:
		if not check('req_' + req_id, found_ids.has(req_id), 'Manca il sistema con id ' + req_id):
			return

	for sys_id in found_ids:
		var sys: Dictionary = found_ids[sys_id]
		var deps = sys['dependencies']
		var sys_order = sys['order']
		if not check('deps_array_' + sys_id, typeof(deps) == TYPE_ARRAY, 'Le dipendenze del sistema ' + sys_id + ' devono essere un array'):
			return
		for dep in deps:
			if not check('dep_exists_' + str(dep), found_ids.has(dep), 'La dipendenza ' + str(dep) + ' non esiste nella mappa'):
				return
			var dep_order = orders[dep]
			check('dep_order_' + sys_id, dep_order < sys_order, 'Il sistema ' + sys_id + ' deve avere un ordine maggiore della sua dipendenza ' + str(dep))

	var interpreter_deps: Array = found_ids['story_interpreter']['dependencies']
	check('interpreter_dep_ui', interpreter_deps.has('dialogue_ui'), 'story_interpreter deve dipendere da dialogue_ui')

	var state_deps: Array = found_ids['game_state']['dependencies']
	check('state_dep_interpreter', state_deps.has('story_interpreter'), 'game_state deve dipendere da story_interpreter')

